$excel.Visible = $false; $excel.DisplayAlerts = $false
$wb = $excel.Workbooks.Open($excelPath)
$ws = $wb.Worksheets.Item(1)
$rows = $ws.UsedRange.Rows.Count
$excelMap = @{}
$unmapped = @{}
for ($r = 1; $r -le $rows; $r++) {
  $code = ([string]$ws.Cells.Item($r,1).Value2).Trim()
  $posName = [string]$ws.Cells.Item($r,2).Value2
  if ([string]::IsNullOrWhiteSpace($code)) { continue }
  $expected = Map-ExcelPosition $posName
  if ($null -eq $expected) { $unmapped[$code] = $posName }
  $excelMap[$code] = @{ PositionName = $posName; Expected = $expected }
}
$wb.Close($false); $excel.Quit()

$dbMap = @{}
$parseErrors = 0
Select-String -Path $sqlPath -Pattern 'INSERT \[dbo\]\.\[HRS_Employee\]' -Encoding UTF8 | ForEach-Object {
  $line = $_.Line
  $idx = $line.IndexOf('VALUES (')
  if ($idx -lt 0) { $parseErrors++; return }
  $start = $idx + 8
  $end = $line.LastIndexOf(')')
  if ($end -le $start) { $parseErrors++; return }
  $parts = Split-SqlValues $line.Substring($start, $end - $start)
  if ($parts.Count -lt 39) { $parseErrors++; return }
  $empCode = Unquote $parts[1]
  $posId = Unquote $parts[38]
  if (-not [string]::IsNullOrWhiteSpace($empCode)) { $dbMap[$empCode] = $posId }
}

$mismatch = @(); $updates = @(); $notfound = @(); $matched = 0; $ok = 0
foreach ($kv in $excelMap.GetEnumerator()) {
  $code = $kv.Key
  $expected = $kv.Value.Expected
  if ($null -eq $expected) { continue }
  if (-not $dbMap.ContainsKey($code)) { $notfound += "$code | $($kv.Value.PositionName) | expected=$expected"; continue }
  $matched++
  $current = $dbMap[$code]
  if ($current -ne $expected) {
    $mismatch += "$code | sql=$current | excel=$expected | $($kv.Value.PositionName)"
    $updates += "Update HRS_Employee Set PositionID = N'$expected', UpdatedDate = GetDate(), UpdatedUser = N'IMPORT' Where EmployeeCode = N'$code' And IsDeleted = 0;"
  } else { $ok++ }
}

$patchLines = @(
'Use SIMS_NET','Go','-- Dong bo PositionID HRS_Employee theo chuc vu - nhan vien.xlsx (24.09.2026)','-- Tong cap nhat: ' + $updates.Count,'Begin Try','Begin Tran'
) + $updates + @('Commit Tran','End Try','Begin Catch','If @@TranCount > 0 Rollback Tran;','Declare @Err nvarchar(4000) = Error_Message();','Raiserror(@Err, 16, 1);','End Catch','Go')

$checkLines = @(
'Use SIMS_NET','Go','-- Bao cao doi chieu chuc vu Excel vs HRS_Employee (24.09.2026)','Select * From (Values'
)
$valLines = @()
foreach ($m in $mismatch) {
  $bits = $m -split ' \| '
  $code = ($bits[0]).Trim()
  $sqlPos = ($bits[1] -replace 'sql=','').Trim()
  $excelPos = ($bits[2] -replace 'excel=','').Trim()
  $name = ($bits[3]).Trim()
  $name = $name.Replace("'","''")
  $valLines += "(N'$code', N'$sqlPos', N'$excelPos', N'$name')"
}
if ($valLines.Count -eq 0) { $valLines += "(N'', N'', N'', N'Khong co chenh lech')" }
$checkLines += ($valLines -join ',') + ') As T(EmployeeCode, PositionID_HienTai, PositionID_Excel, ChucVuExcel)'
$checkLines += 'Order By EmployeeCode'
$checkLines += 'Go'

$patchDir = Split-Path $patchPath -Parent
if (-not (Test-Path $patchDir)) { New-Item -ItemType Directory -Path $patchDir | Out-Null }
($patchLines -join "`r`n") | Set-Content -Path $patchPath -Encoding UTF8
($checkLines -join "`r`n") | Set-Content -Path $checkPath -Encoding UTF8

Write-Output "DB=$($dbMap.Count) MATCHED=$matched OK=$ok UPDATES=$($updates.Count) NOTFOUND=$($notfound.Count) PARSEERR=$parseErrors UNMAPPED=$($unmapped.Count)"
$mismatch
'@
