function Unquote([string]$v) {
  if ($null -eq $v) { return '' }
  $v = $v.Trim()
  if ($v.StartsWith('N''')) { $v = $v.Substring(2) }
  elseif ($v.StartsWith(''')) { $v = $v.Substring(1) }
  if ($v.EndsWith(''')) { $v = $v.Substring(0, $v.Length - 1) }
  return $v
}
